"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[656],{3656:function(e,t,n){n.r(t),n.d(t,{roleLabels107:function(){return o},writingText107ByExemplarId:function(){return s},writingText107Essays:function(){return i}});let o={opening:"起",description:"承",contrast:"轉",stance:"立場",reason:"理由",experience:"經驗",reflection:"合"},i=[{id:"107-essay-01-text",title:"佳作 01",modelType:"經驗升華型",estimatedScore:"16-18",sourceImage:"",summary:"完整呈現「期待—久候—體驗不佳—反思從眾」因果鏈；反思後半略擴到媒體優勢，是學「經驗如何產生觀點」的好材料。 反思中心：從眾與獨立思考。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"I am definitely a foodie. Revelling in mouth-watering treats never fails to intoxicate me with ecstasy. Thus, "},{text:"if there are any famous delicacy",mark:"error",title:"原文錯誤（保留）",note:"there is與單數、there are與複數須一致",suggestion:"if there is any famous delicacy / if there are any famous dishes"},{text:", "},{text:"I will more than willing",mark:"error",title:"原文錯誤（保留）",note:"缺少be動詞",suggestion:"I will be more than willing"},{text:" to wait for a long time just to give it a try. My mother, who also puts much emphasis on eating, is my good partner, and we often explore newly opened restaurants together, "},{text:"which often gave us",mark:"error",title:"原文錯誤（保留）",note:"描述習慣時態應一致",suggestion:"which often gives us"},{text:" a sense of achievement "},{text:"when we find one",mark:"error",title:"原文錯誤（保留）",note:"one指涉不清",suggestion:"when we find one we like"},{text:". Once, we knew from the TV that there was a newly opened pasta restaurant near our home and we decided to have it as our lunch."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", what came into our views when we got the restaurant was a lone building "},{text:"under seidge",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤",suggestion:"under siege"},{text:" by throngs of people. My mother suggested that we come next time but I was eager to try it. As a result, we stood in the line and started waiting. The time dragged and my mother became restless. "},{text:"Nevertheless",mark:"sentence",title:"轉折",note:"保留前文資訊後轉折。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", my heart was filled with joy and excitement."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"After waiting for "},{text:"two solid hours",mark:"comment",title:"把等待寫具體",note:"有實際時間，閱卷者才能相信『久候』。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:", it was finally our turn. We "},{text:"walked in the restaurant",mark:"error",title:"原文錯誤（保留）",note:"進入某處用into",suggestion:"walked into the restaurant"},{text:" in a jubilant mood and relish the laid-back atmosphere in the restaurant. To my disappointment, after another one hour, I "},{text:"walked out the restaurant",mark:"error",title:"原文錯誤（保留）",note:"固定搭配out of",suggestion:"walked out of the restaurant"},{text:" in a gloomy mood. It turned out that this lunch became "},{text:"one of the most horrible experience",mark:"error",title:"原文錯誤（保留）",note:"one of the＋複數名詞",suggestion:"one of the most horrible experiences"},{text:" of mine. The waitress provided "},{text:"poor sevice",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤",suggestion:"poor service"},{text:" while the pasta was "},{text:"too salty and unfresh",mark:"error",title:"原文錯誤（保留）",note:"unfresh不自然",suggestion:"too salty and not fresh"},{text:"."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"The experience teaches me",mark:"error",title:"原文錯誤（保留）",note:"過去經驗帶來的體悟",suggestion:"The experience taught me"},{text:" that "},{text:"the amount of people",mark:"error",title:"原文錯誤（保留）",note:"people可數",suggestion:"the number of people"},{text:" waiting for a restaurant doesn't equal how great it is."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"It is especially true in this social-networking era since "},{text:"we were often misled",mark:"error",title:"原文錯誤（保留）",note:"描述現代普遍現象",suggestion:"we are often misled"},{text:" by a kaleidoscopic variety of new information and advertisements. It also teaches me that I "},{text:"shouldn't always followed",mark:"error",title:"原文錯誤（保留）",note:"情態動詞後接原形",suggestion:"shouldn't always follow"},{text:" the crowd. "},{text:"Not only when",mark:"error",title:"原文錯誤（保留）",note:"原文為片段句",suggestion:"This applies not only when I choose a restaurant but also when I make other decisions."},{text:" "},{text:"I am chosing",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤",suggestion:"I am choosing"},{text:" a restaurant for lunch but also when I am making decisions."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"Since I am exposed to a colossal amount of knowledge, the ability to "},{text:"think independently",mark:"comment",title:"可遷移主張",note:"從一次排隊經驗抽出可泛化的獨立思考。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:" becomes particularly important. The mainstream media of 21st century definitely "},{text:"have overwhelming advantage",mark:"error",title:"原文錯誤（保留）",note:"可數單數advantage需冠詞",suggestion:"media ... have an overwhelming advantage"},{text:" against the traditional ones. Thus, it becomes essential for us to learn to be a qualified modern citizen."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"Despite the fact that it was a terrible experience, it is also thought-provoking."}]}]},{id:"107-essay-02-text",title:"佳作 02",modelType:"心理剖析型",estimatedScore:"17-19",sourceImage:"",summary:"對排隊心理機制分析很深；敘事與反思密度高，適合學「把經驗寫成人群心理學」。 反思中心：需求、價值與自我合理化。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"We were already munching on some roasted sausages when we encountered the long, winding line formed by human bodies. No, a line would be quite an inaccurate analogy; it was more of a human version of the Great Wall of China, with its building material constantly squirming, fanning themselves and straining their necks to despair at its length. It was a sultry mid-July at a nightmarket in Yi-Lan, where "},{text:"we found the breadth of the street thus reduced by the massive structure",mark:"error",title:"原文錯誤（保留）",note:"reduced by搭配較生硬，narrowed by更自然",suggestion:"we found the street narrowed by the massive crowd"},{text:". Unable to quench our curiosity, we sent Dad as a scout to discover the source."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"Ere long we received the intelligence: a famous food stall selling meat buns that was crowned the best of the county. The line was so long and winding that no hint of it could be detected. Curiosity killed the cat, it is known, but it is also said that satisfaction brought it back. We were already on a family vacation, so what's the harm of giving the local food a try?"}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:'It was an hour of squirming, fanning ourselves and straining our necks to peek over heads before we saw the puffs of steam rising into the sky of the sweltering summer night. It was another thirty minutes before we made it through the crowd of heads over which it was seen. My history teacher once told me that "things fought over are things valuable." My tastebuds are naturally insensitive, but as I bit into the precious bun we took all the pain to procure, I thought I sensed a more layered flavor, a more unique aroma. Even though '},{text:"a more pragmatic — and aromantic — part of my brain",mark:"error",title:"原文錯誤（保留）",note:"aromantic是特定心理傾向用詞，此處要表達的是『不浪漫』應用unromantic",suggestion:"a more pragmatic — and unromantic — part of my brain"},{text:" claimed that it was no different from the streetside variety, I believed that it had a deeper, more complex taste that raised it above the mundanes. "},{text:"After all",mark:"sentence",title:"補充判斷",note:"用常理加強說法。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", it would not have attracted so many if it did not deserve its title, would it?"}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"Psychology is a mesmerizing study.",mark:"error",title:"原文錯誤（保留）",note:"補上橋接語，避免反思段落像另起新話題",suggestion:"It was only then that I understood why: psychology is a mesmerizing study."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"High demand raises the value of common objects. As humans naturally tend to avoid pain both physical and emotional, on finding out that the product falls short of expectation, we strive to justify it to lessen disappointment and humiliation."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"Praises of the now-worthy-enough thing proceed to pique the curiosity in more breasts",mark:"error",title:"原文錯誤（保留）",note:"breasts指人的用法過於古雅，讀者容易誤解；praises of改praise for更自然",suggestion:"Praise for the now-seemingly-worthy item goes on to pique more people's curiosity"},{text:" and lengthen the line even more. What is the point of accusing people of being sheep or being prey to folly? "},{text:"After all",mark:"sentence",title:"補充判斷",note:"用常理加強說法。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", we are all prey to the natural tendencies that creep into our behaviors discreetly."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"Right under our judgmental noses.",mark:"error",title:"原文錯誤（保留）",note:"獨立成句造成片段句，應以破折號併入前一句",suggestion:"—— right under our judgmental noses."}]}]},{id:"107-essay-03-text",title:"佳作 03",modelType:"經驗選擇型",estimatedScore:"16-18",sourceImage:"",summary:"花博排隊經驗能導向「不要迷路在潮流」；部分歷史概括過大，可學如何收斂主張。 反思中心：跟風與自我選擇。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"The Flower Exhibition was one of our destinations during my family trip to Taipei in the winter when I was a second grader. Having read a lot of introductions about the event, I looked forward to visiting the region where amazing flowers and "},{text:"the fascinating scenary in Taiwan",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤",suggestion:"the fascinating scenery in Taiwan"},{text:" were displayed through technology. It was also one of the must-see places for the tourists worldwide."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"To gain the ticket to the museum, my family and I got up extremely early that day, which was usual for a relaxing trip. "},{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", as soon as we arrived, there had already been a long line. Furthermore, more and more people got there after us, among which there were even a group of more than twenty Chinese tourists."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"I wondered if all of the liners had read the introduction and were "},{text:"attracted by the displayed",mark:"error",title:"原文錯誤（保留）",note:"displayed為動詞過去分詞，此處需要名詞",suggestion:"attracted by the display / attracted by what was displayed"},{text:", or they were just convinced by the travel agents or the news reports. Since the exhibition occupied a dramatically broad area, no one could visit all museums in a few days. My family and I carefully read the introduction on the Internet and chose the interesting ones in our minds to visit, while most people merely came to see what is popular at that time and "},{text:"got satisfied in that they had seen the brand new things",mark:"error",title:"原文錯誤（保留）",note:"got satisfied in that搭配生硬，非自然英文",suggestion:"felt satisfied simply because they had seen something new"},{text:"."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"If given a second chance, I would like to visit the Flower Exhibition again since I was genuinely moved by the beauty of the blossoms."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", for most people, it was merely "},{text:"a tourists attraction",mark:"error",title:"原文錯誤（保留）",note:"名詞作形容詞時用單數：tourist attraction",suggestion:"a tourist attraction"},{text:" where they visited because it was repeatedly reported. "},{text:"People have learned to enjoy their life since the industrial revolution.",mark:"error",title:"原文錯誤（保留）",note:"原句歷史泛化過大且與主題連結薄弱，屬內容邏輯問題而非文法錯誤",suggestion:"（建議整句刪除，或改為：Ever since consumer culture took hold, more choices have become available to us.）"},{text:" "},{text:"Nevertheless",mark:"sentence",title:"轉折",note:"保留前文資訊後轉折。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", more people are blind."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"They constantly follow the trend and gradually lose their mind. When asked if they really love what they are pursuing, most of them hesitate. As the technology advances rapidly, more and more innovative products will be introduced to the world."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"To find our true concepts and real goals, "},{text:"we have better question ourselves",mark:"error",title:"原文錯誤（保留）",note:"固定用法had better，不可省略had",suggestion:"we had better question ourselves"},{text:' when we are following the trend — "Do I really like it?" '},{text:"Therefore",mark:"sentence",title:"因果",note:"由證據推到結論。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", we may not get lost in the modern society."}]}]},{id:"107-essay-04-text",title:"佳作 04",modelType:"同理敘事型",estimatedScore:"18-19",sourceImage:"",summary:"幾乎全篇用旁觀視角寫一位母親排隊，反思落在「禮物背後的愛」；觀點最具個人性。 反思中心：排隊背後的親情。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"A woman stood quietly in line, her hands clutched tightly on her purse. The air around her hummed pleasantly with whispered conversation — all the people waiting in line seemed to be nervously expecting something. Then, suddenly, a door creaked open, and a girl stepped out."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:'"We\'re open!" As her booming voice traveled down the long line, a ripple of excitement seemed to follow. The woman clutching her purse smiled. As the people filed inside the small shop, they were instructed to look up the menu, put down an order, and take their product with them on their way out.'}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"Despite such a perfectly designed routine, "},{text:"disturbance still occured",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤（occurred雙r）",suggestion:"disturbance still occurred"},{text:" due to the eager people pushing to get inside, causing much annoyance and several small arguments. So it was that when the quiet woman walked out of the shop she was glad to take a big breath of fresh air. Even though waiting in line was tedious work, "},{text:"she was jubilant as she started home with a big box",mark:"error",title:"原文錯誤（保留）",note:"started home較口語，headed home更自然對應敘事語氣",suggestion:"she was jubilant as she headed home with a big box"},{text:" in her arms."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"This is a story of my mother buying a product she saw on TV the week before."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"It was a pudding made so tender that it seemed to melt on your tongue. The story behind the product was a pair of worried parents when their child got braces and did not have appetite to eat anything whatsoever. Desperate, they decided to invent a tender pudding that their child could consume with ease."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"When my mother saw this story on TV, she was deeply touched, and at the time I had just started to put on braces, so my mother had bought the pudding and brought them to me in no time. Even though this happened years ago, I can vividly see the look of satisfaction on my mother's face when I told her I liked the pudding, and "},{text:"seeing that look made me realized",mark:"error",title:"原文錯誤（保留）",note:"make sb + 原形動詞，不可用過去式realized",suggestion:"seeing that look made me realize"},{text:" how much my mother really cared for me. Before this incident I had always thought that the people swarming into popular stores were foolish, but now I realize that their eagerness may as well be the evidence of how much their loved ones meant to them."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"All in all",mark:"sentence",title:"結論信號",note:"提醒讀者文章要收束。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", "},{text:"I have deep respect for ones that submit themselves",mark:"error",title:"原文錯誤（保留）",note:"指人應用those who，而非ones that",suggestion:"I have deep respect for those who submit themselves"},{text:" to waiting in long lines, and I hope that "},{text:"the ones that receive these gifts",mark:"error",title:"原文錯誤（保留）",note:"同上，指人用those who",suggestion:"those who receive these gifts"},{text:" will know how much the gifts are worth."}]}]},{id:"107-essay-05-text",title:"佳作 05",modelType:"秩序觀察型",estimatedScore:"15-17",sourceImage:"",summary:"奶茶促銷排隊觀察很生活化；反思讚賞秩序，但第二段稍短，是學「感想要再往下挖一層」的材料。 反思中心：排隊秩序。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:'After knowing that the "apparent" milk tea was on sale, my mother and I went to the nearest supermarket to see if we were lucky enough to buy a bottle of it. Certainly, both of us were aware of its popularity, so we were not too surprised when seeing people '},{text:"flocking into the supermaket",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤",suggestion:"flocking into the supermarket"},{text:" for the special thing."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"Nevertheless",mark:"sentence",title:"轉折",note:"保留前文資訊後轉折。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", while we expected that younger people were more interested in the \"apparent\" milk tea, we saw many elderly people standing in the long line. What's more, most of them seemed ambitious, and some even had a serious expression on their faces. This was so interesting that my mother and I couldn't help but laugh."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:'Before long, the long line in front of the dairy section disappeared. Instead, another line in front the cashier was formed, with people carrying bottles of the "apparent" milk tea. There weren\'t any apparent milk tea left on the shelf ultimately, of course.'}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"In my opinion",mark:"sentence",title:"立場信號",note:"直接告訴閱卷者：第二段開始表態。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", in the swarm of people, "},{text:"some might bought the special milk tea",mark:"error",title:"原文錯誤（保留）",note:"情態動詞might後接完成式須用have + p.p.",suggestion:"some might have bought the special milk tea"},{text:" "},{text:"out of curiosity",mark:"comment",title:"排隊動機",note:"呼應題目『一時好奇／嘗鮮心理』。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:", whereas others were actually big fans of dairy products."}]},{id:"p5-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", after these people tried once, "},{text:"I don't think most of them tend to have it twice",mark:"error",title:"原文錯誤（保留）",note:"tend to have it twice搭配不自然",suggestion:"I doubt that most of them would want it again"},{text:", since it was quite expensive. "},{text:"Anyway, I felt happy",mark:"error",title:"原文錯誤（保留）",note:"Anyway語氣過於口語，正式作文建議用Overall/In general",suggestion:"Overall, I felt happy"},{text:' to see people in Taiwan willing to line up for things they want instead of cutting lines without discipline. In that case, the "lining up" culture in Taiwan seems quite lovely, but '},{text:"not just fighting with others for food like barbarians",mark:"error",title:"原文錯誤（保留）",note:"not just與前句lovely的對比關係不清楚，rather than更能表達『而不是』",suggestion:"rather than fighting over food like barbarians"},{text:"."}]}]},{id:"107-essay-06-text",title:"佳作 06",modelType:"報導所聞型",estimatedScore:"16-18",sourceImage:"",summary:"用新聞材料寫 Costco 奶茶排隊，是官方允許「報導所聞」的標準示範；最後建議先問需求再行動。 反思中心：媒體從眾與獨立判斷。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"Form A Long Line",mark:"sentence",title:"題目回扣",note:"直接回應題目用語，開門見山。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:" Recently, a Taiwanese brand "},{text:"rolled out a new type of milk tea, and it was sold by Costco exclusively",mark:"error",title:"原文錯誤（保留）",note:"以分詞片語取代and子句，句子更精簡",suggestion:"rolled out a new type of milk tea, sold exclusively by Costco"},{text:". Upon its release, it made the headlines since it led to long lines formed in front of Costcos around Taiwan. Based on some customers, the milk tea was usually sold out within fifteen minutes. "},{text:"In addition",mark:"sentence",title:"補充資訊",note:"補充細節或理由。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", the buyers were seen to carry boxes of milk tea rather than bottles of them."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"Journalists asked some people waiting in line about their motive, and their answers fell into three categories. Some said they wanted to buy and share it with friends, others explained that they just intended to boast about the fact that they purchased it while others couldn't, and some others came here simply because the news was all over the media. Feeling curious, they decided to take a look. So crazy were the buyers that they either abandoned their work or arrived at the wholesale store before its business hours."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"In my point of view, although this kind of craze is common in Taiwan these days, we shouldn't consider it normal. Waiting in lines to get what one wants is reasonable, but the motive of the buyers in this case was just ridiculous. Judging from their replies, I assume that they were simply afraid that they couldn't keep up with the trend and that they might be mocked by their friends and family for being outdated. "},{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:","}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"in my opinion, as an adult with an independent mind, we should make our own decisions rather than being cluelessly led by the mass or the media."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"Fortunately, it was merely a harmless drink this time. In the future, we might be faced with some more complicated issues, such as election and career choice. In this situation, depending on others might be risky since they're not always right and there's no second chance."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"Starting from trivial stuffs such as buying milk tea",mark:"error",title:"原文錯誤（保留）",note:"stuff為不可數名詞，無複數形",suggestion:"Starting from trivial stuff such as buying milk tea"},{text:", we should cultivate the habit of thinking profoundly. For instance, before we rush to the wholesale store, we should ask ourselves if we really need or simply want the milk tea. After this process, if we are still determined to buy it, then go ahead."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"Although waiting in lines might be exhausting, "},{text:"it will pay off in the end",mark:"error",title:"原文錯誤（保留）",note:"內容邏輯與全文立場略有矛盾，非純文法問題",suggestion:"（建議整句改寫，見O8說明）"},{text:"."}]}]},{id:"107-essay-07-text",title:"佳作 07",modelType:"時間成本型",estimatedScore:"17-19",sourceImage:"",summary:"甜甜圈店開幕敘事弧線清楚，並把個人浪費時間推到交通壅塞與公共影響。 反思中心：時間成本與公共影響。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"I can still clearly recall the day when a renowned American donuts shop opened its first Taiwanese branch in the heart of Taipei City. Out of sheer excitement, several friends and I decided to give the famous donuts a try. "},{text:"After all",mark:"sentence",title:"補充判斷",note:"用常理加強說法。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", why not take advantage of the opening discount? "},{text:"Hardly had we arrived at the shop were we stunned by the scene.",mark:"error",title:"原文錯誤（保留）",note:"Hardly...had...固定搭配when，不可用were銜接",suggestion:"Hardly had we arrived at the shop when we were stunned by the scene."},{text:" Instead of a box of heartwarming donuts, we were met with an incredibly long line whose end was too far to be seen. Unwilling to return home without a gain, we headed over to stand in the line."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"We tried to lift our spirits "},{text:"by imaging the richness",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤，缺少in",suggestion:"by imagining the richness"},{text:" of the donuts' chocolate coating, the crispy texture of the well-baked bread, as well as the savory sweetness that would linger on our taste buds for weeks. "},{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", hours of waiting eventually dampened our enthusiasm. My legs were so sore and tired that they almost collapsed under me. It seemed like we were trapped in the endless line for an eternity. As the line marched slowly forward, we could finally catch sight of the shop standing in the distance. Hopes were kindled and "},{text:"morales were heightened",mark:"error",title:"原文錯誤（保留）",note:"morale（士氣）為不可數名詞，無複數形，且拼字不是morales",suggestion:"Morale was heightened"},{text:"."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"Finally, there were only three people, two people, and the last person in front of us! After 3 hours of standing in line, we finally bought the hot donuts! Without hesitation, we bit down on our trophies. Sweetness poured in but closely followed by bittersweet. The donuts were delicious, but not good enough to compensate for 3 hours of waiting! After this experience, I have never spent a second waiting in a long line formed by trend."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"In my opinion",mark:"sentence",title:"立場信號",note:"直接告訴閱卷者：第二段開始表態。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", there is no denying that curiosity can be a strong incentive to stand in a long line for a new trending item that's been raging like a storm."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", "},{text:"the long hours of waiting often is unsensible",mark:"error",title:"原文錯誤（保留）",note:"unsensible非標準英文，應用unwise或not sensible；waiting為主詞時動詞應配合前面hours",suggestion:"the long hours of waiting are often unwise / not sensible"},{text:" since our purchases rarely meet the expectations built by the long wait. Furthermore, a long line also results in public inconveniences such as a blocked traffic and "},{text:"a crowd impossible to squeezed through",mark:"error",title:"原文錯誤（保留）",note:"impossible to + 原形動詞，不用squeezed",suggestion:"a crowd impossible to squeeze through"},{text:" for other passersby."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"Besides, the products bought after the craze fades away are just as good without having to spend hours waiting. Last but not least, before taking a place in a long line, we should ask ourselves whether the products are worth hours of waiting or do we simply try to be like others."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"In my case, I'm rational enough now to resist drifting with the trend and utilize my time efficiently while still getting the goods several months later!"}]}]},{id:"107-essay-08-text",title:"佳作 08",modelType:"問題解方型",estimatedScore:"16-18",sourceImage:"",summary:"由個人不便推到商店與街區影響，再提預約／外送等解方，適合學「感想→做法」。 反思中心：排隊負面影響與解方。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"People tend to "},{text:"form a long line",mark:"comment",title:"回扣題目用語",note:"直接使用題目關鍵片語，切題感強。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:" "},{text:"out of curiosity",mark:"comment",title:"排隊動機",note:"呼應題目『一時好奇／嘗鮮心理』。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:". It was about two years ago when a Japanese pancake shop grandly opened beside my house. "},{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", after the opening ceremony, the swarm of people never seemed to disappear."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"There were people from young to old forming an extremely long and winding line since 7 o'clock every morning. I wonder what kind of attraction could ordinary snacks like pancakes provide? Thus, "},{text:"out of curiosity",mark:"comment",title:"排隊動機",note:"呼應題目『一時好奇／嘗鮮心理』。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:", I carefully stepped into the ever-growing line. "},{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", the line moved so slowly that I merely moved from one sidewalk tree to another after waiting for half an hour!"}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"Anger and angst grew from the bottom of my heart while winding and turning from a corner to another. And finally, when I got to the head of the line, they announced that the pancakes were sold out! How irritating and frustrating it was! Stomping home with heavy steps, thinking that I would probably never forget this terrible lining up experience."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"Regarding this phenomenon and my own lining up experience, "},{text:"I arouse two pieces of reflection and thoughts",mark:"error",title:"原文錯誤（保留）",note:"arouse為及物動詞（使…產生），不能當作『我產生』使用",suggestion:"two reflections arise in my mind / I have drawn two reflections"},{text:"."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"First, while recalling former lining up experiences, I found that forming a long line actually decreases the urge and lowers the anticipation of either the consumers or tourists. While waiting in such a long line, "},{text:"the sense of anger often surpass the sense of happiness",mark:"error",title:"原文錯誤（保留）",note:"主詞the sense為第三人稱單數，動詞須加s",suggestion:"the sense of anger often surpasses the sense of happiness"},{text:" and accomplishment, thus "},{text:"causing bad effects to the shops",mark:"error",title:"原文錯誤（保留）",note:"have/cause an effect on，固定介系詞為on",suggestion:"causing bad effects on the shops"},{text:" or tourist spots. Second, the long lines "},{text:"pose threats and unconvenience",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤：inconvenience",suggestion:"pose threats and inconvenience"},{text:" to their neighborhood by causing traffic jams and creating a noisy environment."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"Take the Japanese pancake store for example, it lies between my house and my bus stop to school. Thus, I have to either squeeze through those noisy people or "},{text:"choose a further routine to get to the bus stop",mark:"error",title:"原文錯誤（保留）",note:"routine（例行公事）與route（路線）混淆，此處應為route",suggestion:"choose a longer route to get to the bus stop"},{text:", but "},{text:"both of them bring me great unconvenience",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤：inconvenience（重複錯誤）",suggestion:"both of them bring me great inconvenience"},{text:". I think that "},{text:"this lining up phenomenon should be replaced and reduced by ways such as",mark:"error",title:"原文錯誤（保留）",note:"phenomenon（現象）用replaced搭配不通順，現象只能被『減少』不能被『取代』",suggestion:"this phenomenon could be reduced through means such as"},{text:" Internet order or delivering system since the technology today has improved."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"To sum up",mark:"sentence",title:"結論信號",note:"收束前文主張。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", I believe that reducing forming long lines in stores and tourist spots is a must, and will surely lead us to a better and brighter society!"}]}]},{id:"107-essay-09-text",title:"佳作 09",modelType:"意象反思型",estimatedScore:"16-18",sourceImage:"",summary:"冰淇淋店久候失望後，把好奇心改寫成「探索未被踩過的小径」；意象與主張一致。 反思中心：把好奇心用於獨特探索。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"On a hot summer day, what's better than to indulge in a refreshing ice-cream? As the image of a creamy treat formed in my mind, I could feel a tang of sweetness in my mouth. That's when I had the urge to try out the well-praised ice-cream shop."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"Overwhelmed with excitement and joy, I headed for the shop. "},{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", upon my arrival, my jovial smile turned upside down and my jaw dropped to the floor. In front of me was a long line that stretched beyond my view."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"Nevertheless",mark:"sentence",title:"轉折",note:"保留前文資訊後轉折。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", my flaming curiosity beckoned me to the line. After standing under the blazing sun for an hour, "},{text:"the burning curiosity I held long ago diminished in the wind",mark:"error",title:"原文錯誤（保留）",note:"long ago與同一天發生的事件時間邏輯矛盾，應改為just moments ago／earlier",suggestion:"the burning curiosity I had held just moments ago diminished in the wind"},{text:" and was replaced with frustration and disappointment. To make the matter worse, the long-waited ice-cream was just as ordinary as the ones in a supermarket."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"Curiosity killed the cat."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"In the case of my personal experience, I think curiosity killed the spirit. This phenomenon of forming a long line is without doubt often fueled by curiosity and "},{text:"more often than not, the results are a disappointment",mark:"error",title:"原文錯誤（保留）",note:"results（複數）與a disappointment（單數）數量不一致",suggestion:"more often than not, the result is a disappointment / the results are disappointing"},{text:"."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"I personally think that this curiosity burning inside us could be utilized in a more meaningful way. "},{text:"Instead of going with the fad and try what everyone is doing",mark:"error",title:"原文錯誤（保留）",note:"and前後動名詞須平行：going...and trying...",suggestion:"Instead of going with the fad and trying what everyone is doing"},{text:", why not hold this burning desire of trying new things as a torch to guide us on an adventure where the grass has not yet been trodden?"}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"Because after all, what we will remember is not the hours spent on waiting in a line, but the uniqueness of the paths we laid by ourselves."}]}]},{id:"107-essay-10-text",title:"佳作 10",modelType:"原因列舉型",estimatedScore:"15-17",sourceImage:"",summary:"跟風原因多元、很適合背「原因菜單」；語言錯誤較密，正好練錯誤熱區。 反思中心：跟風原因與獨立思考。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"Nowadays, forming a long line to try out new things has become a common phenomenon and a popular trend. More and more people are willing to sacrifice hours and hours of their free time just to line up to try out things never before seen, and these people can be found almost everywhere. Take one of my own experiences for example. Once, a new tea house opened right across the street from my house."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"With overly exaggerated signs and "},{text:"flameboyant brochures",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤",suggestion:"flamboyant brochures"},{text:", the tea house claimed that they have come up with numerous innovative recipes using only organic, quality ingredients that will sure blow the customers' mind. Before long, a ridiculously long line has formed in front of the tea house, all eager to get a taste of the so-called \""},{text:"unique and incomparible",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤",suggestion:"unique and incomparable"},{text:'" drinks. Upon seeing this, I was first unphased by the crowd gushing over the vibrant-looking drinks. But soon, I surrendered to my curiosity and finally decided to give it a try.'}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"After hours and hours of standing in line, with my legs aching and my patience crumbling, I finally got my drink. With intense curiosity and high expectations, I took a sip from the drink and immediately regretted my decision. The taste of it was bland and artificial, and "},{text:"the vibrant color is sure caused by",mark:"error",title:"原文錯誤（保留）",note:"副詞需加-ly：surely",suggestion:"the vibrant color is surely caused by"},{text:" the synthetic pigments added to the drink. I sighed and take a look back at the line which is still growing, and wondered: "},{text:"Does these people lining up really know",mark:"error",title:"原文錯誤（保留）",note:"these people為複數，助動詞應用Do而非Does",suggestion:"Do these people lining up really know"},{text:" what they are sacrificing time and money for? Did they come because they really understand the value of the product, or did they come simply because rumors and false advertisements?"}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"After this incident, I spent a lot of time pondering the reasons behind this phenomenon and finally came up with a conclusion: "},{text:"The reasons to why people spend so much time",mark:"error",title:"原文錯誤（保留）",note:"reason後接why需搭配that子句，不用because；並注意reason(s)與is/are的單複數一致",suggestion:"The reason why people spend so much time...is that"},{text:" and money lining up to try new things is because firstly, "},{text:"they want to go with friend and families",mark:"error",title:"原文錯誤（保留）",note:"friend應為複數friends；families通常指多個家庭，此處應為單數family",suggestion:"they want to go with friends and family"},{text:", thus giving them a sense of participation and security, instead of feeling alone and left out; Secondly, they try new things because they want to be at the head of popular trends."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"They consider themselves pioneers, so they must keep up with the ever changing world and always be the first to try new things, hence satisfying their pride. Last but not least, it is only human nature that we get attracted by new things."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"Well goes the saying",mark:"error",title:"原文錯誤（保留）",note:"Well goes the saying非標準英文說法",suggestion:"As the saying goes / So goes the saying"},{text:': "There is nothing new under the sun". '},{text:"The tingling excitement of experiencing new things are rare",mark:"error",title:"原文錯誤（保留）",note:"主詞為excitement（單數），動詞應用is",suggestion:"The tingling excitement of experiencing new things is rare"},{text:", thus urging people to "},{text:"form a long line",mark:"comment",title:"回扣題目用語",note:"直接使用題目關鍵片語，切題感強。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:" to try out new things. Though being said, we should still think twice before we act, and avoid being blinded by convincing ads and false advertisement."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"We should learn to "},{text:"think independently",mark:"comment",title:"可遷移主張",note:"從一次排隊經驗抽出可泛化的獨立思考。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:", and know what we really want, not just follow unrealistic trends and waste all our time and money on forming a long line to merely try new things."}]}]},{id:"107-essay-11-text",title:"佳作 11",modelType:"穩健模板型",estimatedScore:"16-18",sourceImage:"",summary:"架構穩：新餐廳→長隊→失望→下次先評估；適合作為第一次仿寫骨架。 反思中心：需求判斷與時間成本。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"It's a common experience that people stand in line to wait for buying some products; however, it sometimes doesn't pay to do it. It was once reported that a restaurant was newly opened near my house."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"Out of curiosity",mark:"comment",title:"排隊動機",note:"呼應題目『一時好奇／嘗鮮心理』。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:", my family decided to give it a try. "},{text:"Not until we stepped out our house did we found out",mark:"error",title:"原文錯誤（保留）",note:"step out of固定搭配須加of；did引導的倒裝句後動詞須用原形find",suggestion:"Not until we stepped out of our house did we find out"},{text:" that it had formed a long line. We were so shocked as we didn't expect that it would be so popular that it took us approximately an hour to wait in line."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"Nonetheless, it was not until we eventually got into the restaurant and had meals that we regretted. Much to our regret, the dishes didn't meet our satisfaction. Although the food was well-prepared, we all thought that it didn't deserve a long time of waiting."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"Such experience did give me an opportunity to reflect on the phenomenon of forming a long line."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"People may do it for several reasons, "},{text:"such as out of curiousity",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤",suggestion:"such as out of curiosity"},{text:", wanting to try new things. Sometimes they don't even know what they are waiting for. They tend to follow the fad without pondering if they really need to do so."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"What's worse, "},{text:"such situation may bring about terrible traffic congestion",mark:"error",title:"原文錯誤（保留）",note:"situation為可數名詞，需加冠詞a",suggestion:"such a situation may bring about terrible traffic congestion"},{text:" or garbage strewn all over the floor. "},{text:"Therefore",mark:"sentence",title:"因果",note:"由證據推到結論。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", we should think twice "},{text:"whether it deserves to wait for",mark:"error",title:"原文錯誤（保留）",note:"deserve to wait for搭配不自然，worth the wait更道地",suggestion:"whether it is worth the wait"},{text:", not just because of fad, before making a decision. Otherwise, it might turn out to be a "},{text:"waste of time",mark:"comment",title:"時間成本點",note:"把排隊轉成可討論的價值判斷。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:". "},{text:"As far as I'm concerned",mark:"sentence",title:"立場信號",note:"個人看法的穩妥開場。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", I would consider carefully instead of springing into action simply after watching news reports."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"I would keep the lesson of this experience in mind and hope that it would not happen again."}]}]},{id:"107-essay-12-text",title:"佳作 12",modelType:"現象解釋型",estimatedScore:"16-18",sourceImage:"",summary:"先解釋資訊快速傳播再寫排隊經驗，現象解釋充分；個人過程可再補厚。 反思中心：網路爆紅、價值與時間。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"Owing to the convenience brought by advanced information technologies like the Internet or the smartphones, "},{text:"news and informations can be spearded widely",mark:"error",title:"原文錯誤（保留）",note:"information不可數無複數；spearded為spread的拼字/形態錯誤（spread過去式仍是spread）",suggestion:"news and information can be spread widely"},{text:" and quickly within the modern society. Under such a circumstance, it's rather usual for a tourist attraction or a restaurant to become famous and popular overnight. And the phenomenon of people forming long lines is thus created."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"Especially in Tainan, a paradise for local as well as foreign tourists, this phenomenon is quite common. For instance, there is an extraordinary coffee shop around my house "},{text:"which serves great coffee and cusines",mark:"error",title:"原文錯誤（保留）",note:"拼字錯誤：cuisine；cuisine作『菜餚』解通常不加s",suggestion:"which serves great coffee and cuisine"},{text:". It has been my habit to visit there in my spare time. "},{text:"Sitting by the sun-lit table",mark:"error",title:"原文錯誤（保留）",note:"and前後動名詞須平行：Sitting...and having...",suggestion:"Sitting by the sun-lit table...and having a nice cup of coffee is one of the most gleeful experiences"},{text:" in the atmospheric and spacious coffee shop and have a nice cup of coffee is one of the most gleeful experiences."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", on a weekend in November, I headed cheerfully toward the coffee shop just as usual, only to find that there was "},{text:"an unprecedented long line infront of it",mark:"error",title:"原文錯誤（保留）",note:"in front of應為三個單字",suggestion:"an unprecedented long line in front of it"},{text:". The reason for that is that, "},{text:"after the shop appeared on an online news",mark:"error",title:"原文錯誤（保留）",note:"news不可數，appeared on an online news文法不通，應加report等可數名詞",suggestion:"after the shop appeared in an online news report"},{text:" earlier that month, it has become a huge attraction for tourists. "},{text:"Nevertheless",mark:"sentence",title:"轉折",note:"保留前文資訊後轉折。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", to my surprise, the crowds were gone merely a month later. It turned out that they were chasing the fashion and "},{text:"started to form a line infront of another shop",mark:"error",title:"原文錯誤（保留）",note:"同上，in front of拼寫錯誤（重複）",suggestion:"started to form a line in front of another shop"},{text:"."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"As far as I'm concerned",mark:"sentence",title:"立場信號",note:"個人看法的穩妥開場。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", such phenomenon is not very desirable."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"After all",mark:"sentence",title:"補充判斷",note:"用常理加強說法。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", these people forming lines are usually just motivated by a fad that will subside in no time. They visit the places for fashion instead of their true values. Not knowing how to appreciate the attractions' values, they might end up damaging them."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"Also, being in a long line is rather time-consuming. "},{text:"In my opinion",mark:"sentence",title:"立場信號",note:"直接告訴閱卷者：第二段開始表態。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", people can make good use of time and do more meaningful things such as helping others or improving themselves instead of waiting in long lines just to catch up with the trends. Especially in a modern society where time is money, chasing fashion can sometimes be a waste of our precious time. "},{text:"To sum up",mark:"sentence",title:"結論信號",note:"收束前文主張。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", I personally don't like the phenomenon of blindly chasing the trends and forming a long, dreadful line."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"At the end of the day, it may be harmless to notice and be fond of the fashion trends, but we have to evaluate them with our free will and avoid blindly obeying them or following the crowds meaninglessly."}]}]},{id:"107-essay-13-text",title:"佳作 13",modelType:"條件判斷型",estimatedScore:"16-18",sourceImage:"",summary:"不是全盤反對排隊，而是區分必要等候與盲目跟風，條件式判斷很值得學。 反思中心：禮貌排隊與盲目久候的區分。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"Getting in lines is a common and essential part of our daily lives. Whether we go to a public toilet, dine in a restaurant, go shopping or travel to a tourist attraction, we often have to "},{text:"form a long line",mark:"comment",title:"回扣題目用語",note:"直接使用題目關鍵片語，切題感強。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:" and wait for a long period of time continuously. "},{text:"Nevertheless",mark:"sentence",title:"轉折",note:"保留前文資訊後轉折。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", this situation is getting more and more frequent nowadays."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"Owing to the promotion of media and the development of the Internet, information is more accessible and convenient to acquire than before. As a consequence, when a new store or tourist spot opens, we can often see on the news that many people are waiting in line, sometimes just because they heard other people recommending it or commercials on the Internet and other media. I personally have experience waiting in line for a long time before."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"My family and I once went to a prestigious restaurant in Taipei, where there are always a large crowd of people waiting to get in. Despite the fact that we arrived there quite early, we ended up waiting for over an hour before we eventually got in. "},{text:"Although the cuisine they served were fairly delicious",mark:"error",title:"原文錯誤（保留）",note:"cuisine為單數不可數名詞，動詞應用was",suggestion:"Although the cuisine they served was fairly delicious"},{text:", the boring and tedious experience of waiting in line made me unwilling to dine there again."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"While it is impossible to avoid waiting in line completely, I believe that it is unnecessary to wait for a long time at a newly opened store or tourist attraction, since we can always go there when there are fewer people."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"Additionally, "},{text:"it is never a pleasant experience",mark:"error",title:"原文錯誤（保留）",note:"全文以I/we為主要視角，此處忽然轉為you，人稱不一致",suggestion:"it is never a pleasant experience...when countless other people are swarming around us"},{text:" to shop or enjoy the view when there are countless other people swarming around you. In my perspective, "},{text:'people nowadays tend to be influenced too much by the Internet or other people; thus feel that they have to "follow the crowd."',mark:"error",title:"原文錯誤（保留）",note:"分號後接動詞片語thus feel缺乏連接詞，造成句子破碎",suggestion:'people nowadays tend to be influenced too much by the Internet or other people, and thus feel that they have to "follow the crowd."'},{text:" This circumstance will result in several negative consequences such as insufficient space, noise pollution and "},{text:"lower living qualities",mark:"error",title:"原文錯誤（保留）",note:"quality of life固定用法，通常不用複數qualities",suggestion:"lower quality of life"},{text:"."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"In my viewpoint, while it is definitely courteous and polite to wait patiently in line with a view to maintaining social order, it is unnecessary and a waste of precious time to wait for a long time for something that is not urgent. Consequently, next time when we prepare to wait in line, "},{text:"we are supposed to ponder on whether it is essential",mark:"error",title:"原文錯誤（保留）",note:"ponder作及物動詞使用時通常不加on，或直接用think about替代",suggestion:"we should ponder whether it is essential / think about whether it is essential"},{text:" to spend time on it."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"This way, we can save a large amount of time as well as keep a pleasant mind while waiting."}]}]},{id:"107-essay-14-text",title:"佳作 14",modelType:"進階詞彙型",estimatedScore:"15-17",sourceImage:"",summary:"中心明確（時間不可逆），但艱深字堆疊造成多處不自然；用來學「難字不是高分保證」。 反思中心：時間不可逆與追逐流行。",paragraphs:[{id:"p1-opening",role:"opening",label:"起",title:"建立排隊場面",note:"先讓讀者知道誰在哪裡為何排隊。",segments:[{text:"Not only Taiwanese but also people all over the world prefer to pursue something prevalent or intriguing owing to their curiosities. Thus, the phenomenon that people "},{text:"form a long line",mark:"comment",title:"回扣題目用語",note:"直接使用題目關鍵片語，切題感強。",suggestion:"可模仿其功能，不一定要抄原句。"},{text:" for the sake of some brand-new fads is somewhat ubiquitous around the world. Take one of my friends for instance."}]},{id:"p2-description",role:"description",label:"承",title:"寫出等待過程",note:"補上隊伍、時間、情緒或動作，讓情形具體。",segments:[{text:"Once, there was a globally renowned restaurant open in Taipei, whereas we resided in Hualien. "},{text:"However",mark:"sentence",title:"轉折",note:"推進事件或觀點衝突。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", incentivized by his tremendous desire to savor the delicacies in it, "},{text:"he resolved to rush to Taipei in order to be the first person entering and consuming in it",mark:"error",title:"原文錯誤（保留）",note:"in order to後應接原形動詞to enter，且consuming in it搭配不自然，改為dine there",suggestion:"he resolved to rush to Taipei in order to be the first person to enter and dine there"},{text:". After arriving at the restaurant by train, he found that there had already been an extremely long line outside."}]},{id:"p3-contrast",role:"contrast",label:"轉",title:"寫出結果或轉折",note:"交代買到／沒買到、失望或新發現，讓情形完整。",segments:[{text:"Nevertheless",mark:"sentence",title:"轉折",note:"保留前文資訊後轉折。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", "},{text:"he still adhered to queue up with a view to feasting on the palatable cuisines there",mark:"error",title:"原文錯誤（保留）",note:"adhere to後應接名詞/動名詞而非原形queue；adhered to queue up為錯誤搭配",suggestion:"he still insisted on queuing up, hoping to feast on the delicious food there"},{text:". Eventually, he made it to step into the restaurant, having a grand meal, with three hours waiting for it. "},{text:"Such an insanity was it to queue up for spending quite a long time.",mark:"error",title:"原文錯誤（保留）",note:"原句倒裝結構錯誤，主詞it與was位置混亂，語意不清",suggestion:"Such was the insanity of queuing up for such a long time."},{text:" In my perspective, it is literally a crazy determination that "},{text:"there are a myriad of people decide to await until they are able to enter the restaurant or else",mark:"error",title:"原文錯誤（保留）",note:"缺少關係代名詞who連接people與decide，造成句子破碎；or else語意不明應刪除",suggestion:"there are a myriad of people who decide to wait until they are able to enter the restaurant"},{text:"."}]},{id:"p4-stance",role:"stance",label:"立場",title:"提出心得主張",note:"第二段必須先有清楚看法，不能只繼續說故事。",segments:[{text:"When elapsing, time is irreversible.",mark:"error",title:"原文錯誤（保留）",note:"分詞構句When elapsing缺乏明確主詞，語意不清",suggestion:"As time elapses, it becomes irreversible."}]},{id:"p5-reason",role:"reason",label:"理由",title:"用原因或影響支持看法",note:"至少一層清楚理由，最好再補例子或影響。",segments:[{text:"Therefore",mark:"sentence",title:"因果",note:"由證據推到結論。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", it is of crucial importance to manage the time to do the more imperative things, rather than merely waiting in line and wasting time. Were it not for queuing up, people could have had an opportunity to complete something meaningful."}]},{id:"p6-experience",role:"experience",label:"經驗",title:"回扣前文經驗",note:"讓反思由前面排隊經驗長出來，不要各說各話。",segments:[{text:"Indulging themselves into the awe-inspiring natural sceneries is far more fabulous. "},{text:"Moreover",mark:"sentence",title:"補充理由",note:"往上加一層支持。",suggestion:"這類信號語可套到別題：保留功能，更换內容。"},{text:", "},{text:"some people queue up for something by virtue of being motivated by transcient fads",mark:"error",title:"原文錯誤（保留）",note:"transcient拼字錯誤（transient）；by virtue of being motivated by為重複疊加的因果標記，宜簡化",suggestion:"some people queue up simply because they are drawn in by transient fads"},{text:". As the fads vanish, what they have done would be inconsequential."}]},{id:"p7-reflection",role:"reflection",label:"合",title:"收束教訓",note:"把理由或例子收回中心主張，並可給出下次判斷。",segments:[{text:"Hence, "},{text:"cherish every subtle part of time",mark:"error",title:"原文錯誤（保留）",note:"subtle part of time搭配不自然，fleeting moment更道地表達『稍縱即逝的時間』",suggestion:"cherish every fleeting moment"},{text:" for the purpose of pursuing significant objectives, and never allow the time to slip away from your hands."}]}]}],s=Object.fromEntries(i.map(e=>{var t;let n=null===(t=e.id.match(/107-essay-(\d+)/))||void 0===t?void 0:t[1];return["107-essay-".concat(n),e]}))}}]);